llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Laninamivir octanoate, a long-chain ester prodrug, has only 15% oral bioavailability in humans, below the 20% threshold; this is the most relevant low-F analog for the lipophilic esterified query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "DINCH, a lipophilic dicarboxylate ester, is almost completely bioavailable in humans, but it lacks the beta-lactone and N-formyl-leucine motif and is not a locally acting lipase inhibitor.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "DVAS, a dodecyl ester of an amino-acid derivative, shows about 60% oral bioavailability in humans, but it is a prodrug without the beta-lactone and is not designed for gastrointestinal-local action.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C29"],
      "claim": "Chloramphenicol palmitate, a long-chain fatty acid ester prodrug, is almost completely bioavailable in children, but it is hydrolyzed to the well-absorbed chloramphenicol, unlike the query which acts locally and is minimally absorbed.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "Perindopril has high oral bioavailability (about 66%), but it is a small ACE-inhibitor prodrug with no long alkyl chain or beta-lactone, so transferability to the query is low.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a GI lipase inhibitor with negligible systemic absorption. The only structurally relevant low-F record (laninamivir octanoate, 15%) supports F < 20%, while the many high-F ester prodrug records are not transferable because they are absorbed prodrugs lacking the beta-lactone/local-action design.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is included in the evidence set.",
    "Most high-F records are for ester prodrugs designed for systemic absorption, limiting their relevance to the query's non-absorbable lipase-inhibitor mechanism."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

